package eval

func contentTagsSuite() Suite {
	base := sessionZeroSettingsSuite()
	spiderContent := map[string]any{"content_id": "content-spider", "kind": "scene", "text": "A giant spider descends.", "tags": []any{"arachnophobia", "combat"}}
	secretContent := map[string]any{"content_id": "content-secret", "kind": "scene", "text": "A secret door opens.", "tags": []any{"secret"}}
	untaggedContent := map[string]any{"content_id": "content-secret", "kind": "scene", "text": "A secret door opens.", "tags": []any{}}
	return Suite{ID: "074-content-tags", Name: "Campaign Play 074: Content Tags", Tests: append(base.Tests,
		playTest("play-content-tags-create-campaign", "DM creates a fresh campaign for tagged content", "POST", "/v1/play/campaigns", map[string]any{"id": "play-074", "name": "Tagged Content", "max_players": 2}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"id": "play-074", "name": "Tagged Content", "owner": "dm", "status": "lobby", "max_players": 2}),
		playTest("play-content-tags-join-player-a", "Player A joins the tagged-content campaign", "POST", "/v1/play/campaigns/play-074/members", map[string]any{"character_id": "play-074-a", "name": "Mira", "class": "ranger"}, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"username": "player-a", "character_id": "play-074-a", "name": "Mira", "class": "ranger"}),
		playTest("play-content-tags-join-player-b", "Player B joins the tagged-content campaign", "POST", "/v1/play/campaigns/play-074/members", map[string]any{"character_id": "play-074-b", "name": "Oren", "class": "wizard"}, map[string]string{"Authorization": playerBAuth}, 201, map[string]any{"username": "player-b", "character_id": "play-074-b", "name": "Oren", "class": "wizard"}),
		playTest("play-content-create-unauthenticated", "Unauthenticated content creation is rejected", "POST", "/v1/play/campaigns/play-074/content", spiderContent, nil, 401, nil),
		playTest("play-content-create-player-forbidden", "Players cannot create content", "POST", "/v1/play/campaigns/play-074/content", spiderContent, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-content-create-empty-id", "Content IDs must be nonempty", "POST", "/v1/play/campaigns/play-074/content", map[string]any{"content_id": "", "kind": "scene", "text": "A giant spider descends.", "tags": []any{"arachnophobia"}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-content-create-empty-kind", "Content kinds must be nonempty", "POST", "/v1/play/campaigns/play-074/content", map[string]any{"content_id": "content-empty-kind", "kind": "", "text": "A giant spider descends.", "tags": []any{"arachnophobia"}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-content-create-empty-text", "Content text must be nonempty", "POST", "/v1/play/campaigns/play-074/content", map[string]any{"content_id": "content-empty-text", "kind": "scene", "text": "", "tags": []any{"arachnophobia"}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-content-create-empty-tags", "Content creation requires at least one tag", "POST", "/v1/play/campaigns/play-074/content", map[string]any{"content_id": "content-empty-tags", "kind": "scene", "text": "A giant spider descends.", "tags": []any{}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-content-create-blank-tag", "Content tags must be nonempty strings", "POST", "/v1/play/campaigns/play-074/content", map[string]any{"content_id": "content-blank-tag", "kind": "scene", "text": "A giant spider descends.", "tags": []any{"arachnophobia", ""}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-content-create-duplicate-tag", "Content tags must be unique", "POST", "/v1/play/campaigns/play-074/content", map[string]any{"content_id": "content-dupe-tag", "kind": "scene", "text": "A giant spider descends.", "tags": []any{"combat", "combat"}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTestExactJSON("play-content-create-spider", "DM creates exact tagged spider content", "POST", "/v1/play/campaigns/play-074/content", spiderContent, map[string]string{"Authorization": dmAuth}, 201, spiderContent),
		playTest("play-content-create-duplicate-id", "Duplicate content IDs conflict", "POST", "/v1/play/campaigns/play-074/content", spiderContent, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTestExactJSON("play-content-create-secret", "DM creates a second tagged content record", "POST", "/v1/play/campaigns/play-074/content", secretContent, map[string]string{"Authorization": dmAuth}, 201, secretContent),
		playTest("play-content-tags-update-player-forbidden", "Players cannot update content tags", "PUT", "/v1/play/campaigns/play-074/content/content-secret/tags", map[string]any{"tags": []any{}}, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-content-tags-update-blank", "Updated tags must be nonempty strings when present", "PUT", "/v1/play/campaigns/play-074/content/content-secret/tags", map[string]any{"tags": []any{"secret", ""}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-content-tags-update-duplicate", "Updated tags must be unique", "PUT", "/v1/play/campaigns/play-074/content/content-secret/tags", map[string]any{"tags": []any{"secret", "secret"}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-content-tags-update-missing", "Unknown content tag updates return 404", "PUT", "/v1/play/campaigns/play-074/content/content-missing/tags", map[string]any{"tags": []any{"secret"}}, map[string]string{"Authorization": dmAuth}, 404, nil),
		playTestExactJSON("play-content-tags-update-untagged", "DM can replace tags with an empty untagged list", "PUT", "/v1/play/campaigns/play-074/content/content-secret/tags", map[string]any{"tags": []any{}}, map[string]string{"Authorization": dmAuth}, 200, untaggedContent),
		playTest("play-content-list-empty-exclude-tag", "exclude_tag must be nonempty when present", "GET", "/v1/play/campaigns/play-074/content?exclude_tag=", nil, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTestExactJSON("play-content-list-dm-exclude-sees-all", "DM ignores exclude_tag and sees all content in creation order", "GET", "/v1/play/campaigns/play-074/content?exclude_tag=arachnophobia", nil, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"content": []any{spiderContent, untaggedContent}}),
		playTestExactJSON("play-content-list-player-filtered", "Players exclude matching tagged content while keeping untagged records", "GET", "/v1/play/campaigns/play-074/content?exclude_tag=arachnophobia", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"content": []any{untaggedContent}}),
		playTestExactJSON("play-content-list-player-no-filter", "Players see all records without exclude_tag", "GET", "/v1/play/campaigns/play-074/content", nil, map[string]string{"Authorization": playerBAuth}, 200, map[string]any{"content": []any{spiderContent, untaggedContent}}),
	)}
}
